from part3 import M, add

add(66, "ดาวศุกร์สองดวง", "เลขที่รวมกันได้ 12 เป็นกำลังของดาวราหู ตำราว่าหลงใหลและมัวเมาง่าย ทำอะไรมักไม่ค่อยไตร่ตรอง ทุ่มเททั้งตัว",
    "", "ควรระวังการหลงอารมณ์ยั่วยวนและความมัวเมาต่าง ๆ และยั้งคิดก่อนตัดสินใจเสมอ")
add(67, "ดาวศุกร์กับดาวเสาร์", "เลขที่ความสดชื่นของดาวศุกร์มาพบกับอุปสรรคของดาวเสาร์ ผลจึงสุก ๆ ดิบ ๆ ไม่ดีไม่ร้ายจริง ตำราจัดว่าเป็นเลขที่ไม่ค่อยดี",
    "", "อาจผิดหวังเรื่องความรัก ครอบครัวมีความขัดแย้งหรือแตกแยก ขัดแย้งทั้งกับตนเองและผู้อื่น และบั้นปลายชีวิตอาจตกต่ำ จึงไม่แนะนำให้ใช้")
add(68, "ดาวศุกร์กับดาวราหู", "เลขที่ตำราว่าเป็นเลขมัวเมาอีกเลขหนึ่ง บ่งถึงความมัวเมาในอุดมคติและอบายมุข รวมถึงความหลงใหลคลั่งไคล้ในศาสนาจนเกินพอดี",
    "", "ควรระวังการหลงมัวเมา และการทำตัวให้เด่นเกินไป")
add(69, "ดาวศุกร์กับดาวเกตุ", "เลขอ่อนที่ใจอ่อน ชอบเพ้อฝัน แต่รวมกันได้ 15 ซึ่งเป็นกำลังดาวจันทร์ ตำราว่าเป็นเลขดีที่ผู้ใหญ่คอยอุปถัมภ์ค้ำชู",
    "มีผู้ใหญ่อุปถัมภ์", "ใจอ่อน ชอบเพ้อฝัน อาจตกอยู่ใต้อำนาจผู้อื่นง่าย")
add(70, "ดาวเสาร์กับดาวมฤตยู", "ตำราถือว่าเป็นเลขร้ายมาก บ่งถึงความโหดร้ายและแรงกดดันจากอำนาจเร้นลับ บั้นปลายชีวิตอาจลำบากและโดดเดี่ยว",
    "", "ควรระวังโรคทางประสาท ภาวะกดดันทางใจ ปัญหาหนี้สิน การถูกลักขโมย และภัยธรรมชาติ ตำราแนะนำให้หลีกเลี่ยง ถ้าผลรวมของชื่อได้เลขนี้และกังวล ควรปรึกษาผู้รู้หรือพิจารณาเลือกชื่อใหม่ ผลนี้เป็นเพียงความเชื่อ ไม่ใช่การตัดสินชีวิต")
add(71, "ดาวเสาร์กับดาวอาทิตย์", "ตำราถือว่าเป็นเลขร้าย บ่งถึงการถูกจำกัดสิทธิอำนาจ การตกจากตำแหน่ง การถูกใส่ร้าย และความหลงมัวเมาในสิ่งผิด ๆ",
    "", "ควรระวังเรื่องตำแหน่งหน้าที่ การถูกใส่ร้าย และความมัวเมา ตำราแนะนำให้เปลี่ยนหรือหลีกเลี่ยง")
add(72, "ดาวเสาร์กับดาวจันทร์", "เลขที่ส่งเสริมให้เจริญรุ่งเรืองด้วยชะตาที่เข้มแข็ง แต่ชีวิตมักวุ่นวาย ตำราว่าให้ผลเสียมากกว่าดี",
    "ชะตาเข้มแข็ง มีโอกาสรุ่งเรือง", "ชีวิตวุ่นวาย ถ้าเป็นชายมักลำบาก ถ้าเป็นหญิงมักเจอเรื่องร้ายบ่อย และมีโรคเรื้อรังได้")
add(73, "ดาวเสาร์กับดาวอังคาร", "ตำราว่าเป็นดาวบาปเคราะห์ทั้งคู่ เสาร์แทนอุปสรรค อังคารแทนการทำลาย บ่งถึงชีวิตที่มักหักกลางคัน ไม่ราบรื่น และต้องเริ่มต้นใหม่บ่อย",
    "ลุกขึ้นเริ่มต้นใหม่ได้เสมอ", "ระวังการผ่าตัด อุบัติเหตุ การล้มละลาย และไม่ควรจริงจังกับชีวิตจนเกินไป")
add(74, "ดาวเสาร์กับดาวพุธ", "เลขที่ตำราว่าดีพอสมควร เพราะเป็นธาตุดินทั้งคู่ ส่งเสริมความกลมเกลียวและความสำเร็จตามสมควร ชีวิตก้าวหน้าแต่ไม่ถึงจุดสูงสุด",
    "ก้าวหน้าตามลำดับ ได้ความสำเร็จพอสมควร", "รวนเร หูเบา เพ้อฝัน วิตกกังวล และมักมีเรื่องทุกข์ใจ")
add(75, "ดาวเสาร์กับดาวพฤหัสบดี", "เลขที่ต้นไม่ดีแต่ปลายดี ชีวิตช่วงแรกวุ่นวายยุ่งเหยิง อาจถูกผู้ใหญ่ตำหนิหรือให้โทษ แต่บั้นปลายจะรุ่งโรจน์",
    "ปลายดี บั้นปลายรุ่งโรจน์", "ช่วงต้นชีวิตวุ่นวาย ไม่เหมาะกับการทำธุรกิจใหญ่ ๆ ถ้าไม่จำเป็นควรหลีกเลี่ยง")
add(76, "ดาวเสาร์กับดาวศุกร์", "เลขคู่ศัตรูที่รวมกันได้ 13 ตำราว่าเป็นเลขให้โทษ คล้ายเลข 67",
    "", "ชีวิตมักอับเฉา ไม่ค่อยมีความสุข ชีวิตคู่อาจร้างลา ตำราแนะนำให้หลีกเลี่ยง")
add(77, "ดาวเสาร์สองดวง", "เลขที่ทุกข์เป็นสองเท่าตามตำรา แต่ก็ส่งเสริมให้เข้มแข็ง อดทน ทรหดเป็นพิเศษ มีคนเกรงใจและมีอำนาจ",
    "เข้มแข็ง อดทนสูง มีอำนาจ ผู้คนเกรงใจ", "ระวังโรคภัยไข้เจ็บที่คอยเบียดเบียนสุขภาพ",
    "งานที่ต้องใช้ความเด็ดขาดและอำนาจ")
add(78, "ดาวเสาร์กับดาวราหู", "เลขที่บ่งถึงความระส่ำระสายของชีวิต วุ่นวาย ใจอ่อนปล่อยให้ผู้อื่นชักจูงได้ง่าย และมักเสียเปรียบตลอด",
    "", "ระวังอุบัติเหตุ คดีความ และการเซ็นค้ำประกัน อย่าใจอ่อนเชื่อใจคนง่าย")
add(79, "ดาวเสาร์กับดาวเกตุ", "เลขที่มีมิตรสหายและญาติมาก อาจได้มรดก และประสบความสำเร็จอย่างโลดโผน แต่มีความทุกข์จากโรคภัยหรือเรื่องเคราะห์ในครอบครัว ตำราจัดว่าไม่ค่อยดี",
    "มีมิตรและญาติมาก อาจได้มรดก ความสำเร็จโลดโผน", "ระวังโรคร้ายหรือโรคประจำตัว และเรื่องบาดเจ็บในครอบครัว")
add(80, "ดาวราหูกับดาวมฤตยู", "ตำราถือว่าเป็นเลขร้ายซ้อนกัน เป็นสัญญาณเตือนให้ระวังเรื่องใหญ่ที่รออยู่ข้างหน้า มักอยู่ในสภาพแวดล้อมไม่ดีหรือถูกกดดัน",
    "", "ควรระวังการถูกข่มเหง อิทธิพลคนไม่ดี และความไม่ราบรื่นของงาน ตำราแนะนำให้หลีกเลี่ยง")
add(81, "ดาวราหูกับดาวอาทิตย์", "เลขอับโชคที่ตำราว่ามักขาดหลักประกันของชีวิต อยู่ไม่เป็นที่ ต้องโยกย้ายบ่อย แต่ถ้าเปลี่ยนที่อยู่บ่อย ๆ ชะตาจะรุ่งเรืองดี",
    "ชะตารุ่งเรืองเมื่อได้เปลี่ยนที่อยู่หรือย้ายถิ่น", "อาจพลัดพรากจากบิดา ถ้าเป็นหญิงอาจมีปัญหาเรื่องคู่ครอง และคู่ครองอาจมีปัญหาเรื่องดวงตา")
add(82, "ดาวราหูกับดาวจันทร์", "เลขที่ตำราว่าชีวิตมักเหงา ว้าเหว่ และถูกกดดันทางจิตใจ จิตใจไม่ค่อยเข้มแข็ง",
    "", "ถูกเบียดเบียนจากคนรอบข้าง ถ้าเป็นชายมักไร้คู่หรือได้คู่ที่เคยผ่านชีวิตมาก่อน ใจหลงง่าย งมงาย ควรบำรุงใจและหาที่พึ่งทางใจ")
add(83, "ดาวราหูกับดาวอังคาร", "ตำราถือเป็นเลขร้าย ชอบวิวาท หลงงมงาย ทำอะไรตามอำเภอใจ",
    "", "ควรระวังอัคคีภัย ภัยจากที่ชุมชน อุบัติเหตุร้ายแรง การผ่าตัด และการถูกนักเลงคุกคาม ใจอ่อนเชื่อใจคนง่ายอาจทำให้ประพฤติผิด")
add(84, "ดาวราหูกับดาวพุธ", "เลขที่ตำราว่าชีวิตวัยรุ่นอาจประพฤติผิดพลาดจนเดือดร้อน และมักประสบชะตากรรมรุนแรง",
    "", "ควรระวังการบาดเจ็บ อุบัติเหตุ การถูกกลั่นแกล้ง คดีความ และการถูกเกลียดชัง")
add(85, "ดาวราหูกับดาวพฤหัสบดี", "เลขที่รวมกันได้ 13 ตำราว่าชีวิตมักไร้หลัก มีอุดมคติผิด ๆ หลงผิดง่าย ลืมง่าย เอาแต่ใจ",
    "", "ระวังความล้มเหลวและขาดที่พึ่ง ตำราแนะนำว่าถ้าบวชเป็นพระควรเปลี่ยนชื่อ-นามสกุลก่อน")
add(86, "ดาวราหูกับดาวศุกร์", "เลขที่ประสบความสำเร็จในทางโลก แต่พ่ายแพ้ทางโลกีย์ หลงมัวเมาในกิเลสและอบายมุข เอาแต่ใจ",
    "สำเร็จดีในทางโลก", "ต้องระวังการหลงมัวเมา การคบชู้ และอบายมุขต่าง ๆ ถ้าไม่รู้จักจุดอิ่มตัวอาจนำไปสู่ความเสียหาย")
add(87, "ดาวราหูกับดาวเสาร์", "เลขที่รวมกันได้ 15 กำลังดาวจันทร์ ทำให้มีเสน่ห์ แต่อ่อนไหว เจ้าอารมณ์ อมทุกข์ หลงผิดง่าย หูเบา",
    "มีเสน่ห์", "เชื่อใจคนง่าย อารมณ์อ่อนไหว บั้นปลายมักตกต่ำหรือไม่ราบรื่น")
add(88, "ดาวราหูสองดวง", "เลขแข็งที่ชีวิตรุดหน้าเร็ว พบความสำเร็จอย่างผาดโผน แต่ราหูพาให้หลงใหล เอาแต่ใจ เห็นแก่ตัว และไม่ฟังคำตักเตือน",
    "ก้าวหน้าเร็ว ประสบความสำเร็จผาดโผน", "ระวังการเห็นผิดเป็นชอบ ไม่ฟังคำเตือน และอุบัติเหตุ")
